Sure! I can help you create a premium and beautiful modern calculator using HTML. Here's a basic structure that will give you a clean, responsive design:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Modern Calculator</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            background-color: #282c34;
            color: white;
        }
        .calculator {
            width: 300px;
            padding: 20px;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
            background-color: #454950;
        }
        .display {
            width: 100%;
            height: 70px;
            margin-bottom: 20px;
            border-radius: 5px;
            text-align: right;
            padding-right: 10px;
            font-size: 24px;
            box-shadow: inset 0 -3px rgba(0, 0, 0, 0.1);
        }
        .buttons {
            display: grid;
            gap: 8px;
            grid-template-columns: repeat(4, 1fr);
        }
        button {
            width: 100%;
            height: 60px;
            font-size: 24px;
            border-radius: 5px;
            cursor: pointer;
            background-color: #3a3d42;
            color: white;
            box-shadow: inset 0 -3px rgba(0, 0, 0, 0.1);
        }
        button:hover {
            background-color: #454950;
        }
    </style>
</head>
<body>

<div class="calculator">
    <input type="text" id="display" readonly placeholder="0" style="width: calc(100% - 20px); padding-left: 10px; border-radius: 5px;">

    <div class="buttons">
        <button onclick="append('7')">7</button>
        <button onclick="append('8')">8</button>
        <button onclick="append('9')">9</button>
        <button onclick="operator('+')">+</button>

        <button onclick="append('4')">4</button>
        <button onclick="append('5')">5</button>
        <button onclick="append('6')">6</button>
        <button onclick="operator('-')">-</button>

        <button onclick="append('1')">1</button>
        <button onclick="append('2')">2</button>
        <button onclick="append('3')">3</button>
        <button onclick="operator('*')">*</button>

        <button onclick="append('0')">0</button>
        <button onclick="decimal()">.</button>
        <button id="equal" onclick="calculate()">=</button>
        <button onclick="operator('/')">/</button>

        <button onclick="clearDisplay()">AC</button>
        <button onclick="deleteLast()">DEL</button>
    </div>

    <script>
        let currentInput = '';

        function append(num) {
            if (currentInput === '0') {
                currentInput = num;
            } else {
                currentInput += num;
            }
            document.getElementById('display').value = currentInput;
        }

        function operator(op) {
            if (!/[\+\-*/]/.test(currentInput)) {
                currentInput += op;
            }
        }

        function calculate() {
            try {
                const result = eval(currentInput);
                document.getElementById('display').value = result;
                currentInput = '';
            } catch (error) {
                alert('Error: Invalid expression');
            }
        }

        function clearDisplay() {
            currentInput = '0';
            document.getElementById('display').value = '0';
        }

        function deleteLast() {
            if (currentInput.length > 1) {
                currentInput = currentInput.slice(0, -1);
            } else {
                currentInput = '0';
            }
            document.getElementById('display').value = currentInput;
        }

        // Example of how to use the buttons
        function simulateButtonPress(buttonId) {
            const buttonElement = document.getElementById(buttonId);
            if (buttonElement) {
                buttonElement.click();
            }
        }

        // Simulate pressing '1' and '='
        simulateButtonPress('1');
        simulateButtonPress('=');

    </script>
</div>

</body>
</html>
```

This code provides a basic structure for a calculator with buttons for digits, operators, decimal point, equal sign, clear, and delete functions. You can further enhance it by adding features like scientific mode or memory functionalities if needed.

Feel free to ask if you need any specific modifications!

